 const controller=useRef<AbortController|null>(null)
 useEffect(()=>{controller.current?.abort();const next=new AbortController();controller.current=next;setLoading(true);setError('');const params=new URLSearchParams({source:query.source});for(const key of ['day','className','teacher','subject']as const)if(query[key])params.set(key,query[key]);void(async()=>{try{const response=await apiFetch('/api/school/analytics/director?'+params,{signal:next.signal});if(!response.ok){if(!next.signal.aborted&&[401,403].includes(response.status))setData(null);throw new Error(response.status===403?'Панель доступна только действующему директору.':response.status===401?'Войдите в школьный кабинет.':'Не удалось загрузить аналитику. Повторите действие.')}const value=await response.json()as Dashboard;if(!valid(value))throw new Error('Сервер не подтвердил данные аналитики.');if(!next.signal.aborted)setData(value)}catch(cause){if(!next.signal.aborted)setError(cause instanceof Error?cause.message:'Нет связи с сервером.')}finally{if(!next.signal.aborted)setLoading(false)}})();return()=>next.abort()},[query,attempt])
 useEffect(()=>{const changed=()=>setAttempt(a=>a+1);window.addEventListener('school-timetable-updated',changed);window.addEventListener('school-ops-updated',changed);return()=>{window.removeEventListener('school-timetable-updated',changed);window.removeEventListener('school-ops-updated',changed)}},[])
 const go=(action:DirectorAction,label:string,primary=false)=>actions[action]?<button type="button" className={`sg-control${primary?' sg-primary':''}`} onClick={actions[action]}>{label}<ArrowRight size={15}/></button>:null
